-- 挑战题库种子数据
-- 50道管理场景挑战题目

-- 1. 战略决策类（10道）
INSERT INTO challenges (title, description, scenario, question, options, correctAnswer, explanation, competencyId, difficulty, points, tags, isActive) VALUES
('市场定位困境', '公司面临多个市场机会', '{"context": "你负责一家SaaS公司，目前有三个潜在市场：企业客户、中小企业、个人用户。资源有限，必须选择一个主攻方向。", "situation": "团队内部意见不一，销售希望做企业客户（单价高），产品希望做个人用户（用户基数大），投资人希望看到快速增长。"}', '作为CEO，你会如何做出决策？', '["立即选择企业客户，因为单价高容易实现营收目标", "选择个人用户，通过用户量吸引投资", "先做市场调研和MVP测试，3个月后基于数据决策", "同时启动三个方向，看哪个先跑通"]', 2, '正确答案是C。战略决策不应凭感觉，应该基于数据和验证。快速启动MVP测试可以用最小成本验证假设，避免资源浪费。选项A和B都是基于单一维度决策，选项D会分散资源导致都做不好。', 1, 'hard', 15, '["战略", "决策", "市场定位"]', TRUE),

('竞品突袭应对', '竞争对手发布类似产品', '{"context": "你的竞争对手刚刚发布了一款与你们高度相似的产品，且价格比你们低30%。", "situation": "销售团队反馈客户开始流失，内部出现恐慌情绪。有人建议立即降价，有人建议加快功能迭代。"}', '你会采取什么策略？', '["立即降价30%以保持竞争力", "加快功能开发，拉开差异化", "保持定价，强化客户成功服务，提升客户留存", "发起市场攻势，加大营销投入抢占市场"]', 2, '正确答案是C。价格战是下策，会损害品牌价值和利润空间。正确做法是强化差异化价值，通过优质服务提升客户粘性。短期内功能差距难以拉开，市场投入ROI不确定，而客户成功是最可控的护城河。', 1, 'hard', 15, '["战略", "竞争", "定价"]', TRUE),

('新业务扩张时机', '是否进入新市场', '{"context": "现有业务稳定增长，团队提出进入一个相关但不同的市场领域。", "situation": "新市场机会很大，但需要投入30%的研发资源，可能影响现有产品的迭代速度。"}', '你如何评估是否进入新市场？', '["立即进入，抓住市场机会窗口", "暂缓，专注做深现有市场", "小团队试点，不影响主业务", "等现有业务达到一定规模后再考虑"]', 2, '正确答案是C。创新需要平衡探索和利用。小团队试点可以低成本验证新机会，既不会影响主业务，又能保持战略灵活性。过早扩张（A）可能导致资源分散，完全不动（B、D）可能错失机会。', 1, 'medium', 10, '["战略", "业务扩张", "资源分配"]', TRUE);

-- 2. 团队管理类（10道）
INSERT INTO challenges (title, description, scenario, question, options, correctAnswer, explanation, competencyId, difficulty, points, tags, isActive) VALUES
('核心员工离职', '技术负责人提出离职', '{"context": "你的技术负责人突然提出离职，他掌握核心技术架构。", "situation": "他的离职可能导致项目延期3个月，团队士气受影响。他表示已经决定，主要原因是职业发展空间受限。"}', '你会如何处理？', '["立即提高薪资待遇，全力挽留", "接受离职，快速招聘替代者", "深入沟通了解真实原因，探讨解决方案和发展路径", "要求交接完成后才能离职，确保项目顺利"]', 2, '正确答案是C。挽留核心员工需要找到真实原因。如果是发展空间问题，可以探讨晋升、轮岗、项目机会等方案。简单加薪（A）治标不治本，强制交接（D）可能适得其反，而快速招聘（B）忽视了知识传承和团队稳定性。', 5, 'hard', 15, '["团队", "人才", "离职"]', TRUE),

('团队冲突调解', '两个部门发生严重分歧', '{"context": "产品和研发部门在一个功能的优先级上产生严重分歧，互相指责对方不配合。", "situation": "产品认为这是客户的强需求，必须立即做。研发认为技术债务太多，应该先重构。双方都有道理，但项目已经延期。"}', '作为高管，你会如何处理？', '["支持产品，客户需求第一", "支持研发，技术债务必须解决", "让他们自己协商解决，不介入", "召开会议，分析数据，共同制定优先级"]', 3, '正确答案是D。管理者不应简单站队，而要帮助团队建立决策机制。通过数据分析客户需求的真实性和紧急性，评估技术债务的影响，然后共同决策。这样既解决了当前问题，又建立了长期的协作机制。', 6, 'medium', 10, '["团队", "冲突", "决策"]', TRUE),

('绩效反馈困境', '如何给予负面反馈', '{"context": "你的一个下属能力很强，但最近三个月工作状态不佳，影响团队进度。", "situation": "你需要在绩效面谈中给予反馈，但担心他情绪化离职，因为他是团队的技术骨干。"}', '你会如何进行这次绩效面谈？', '["淡化问题，主要讲优点，希望他自己改进", "直接指出问题，要求立即改正", "先关心他的状况，了解原因，再给予反馈和支持", "暂时不谈，观察一段时间再说"]', 2, '正确答案是C。有效反馈要建立在信任和理解基础上。先了解状态不佳的原因（可能是个人问题、工作压力等），表达关心，然后给予客观反馈，最后讨论改进方案和提供支持。回避问题（A、D）或简单施压（B）都不是好方法。', 5, 'medium', 10, '["团队", "绩效", "反馈"]', TRUE);

-- 3. 产品管理类（10道）
INSERT INTO challenges (title, description, scenario, question, options, correctAnswer, explanation, competencyId, difficulty, points, tags, isActive) VALUES
('功能优先级决策', '有限资源下的需求选择', '{"context": "你有10个待开发功能，但只有资源做3个。", "situation": "有客户强烈要求的功能、有战略重要但短期ROI不明显的功能、有提升用户体验的小功能。"}', '你会如何确定优先级？', '["优先做客户要求的，保证客户满意度", "优先做战略功能，着眼长期", "使用RICE模型评估，基于数据排序", "做快赢的小功能，快速见效"]', 2, '正确答案是C。产品优先级应该基于系统性的评估方法，如RICE（Reach影响范围、Impact影响程度、Confidence确定性、Effort工作量）。这样可以平衡短期和长期价值，避免主观决策。单一维度决策（A、B、D）都可能导致资源错配。', 3, 'medium', 10, '["产品", "优先级", "决策"]', TRUE),

('用户反馈处理', '如何对待负面反馈', '{"context": "产品发布后收到大量负面反馈，主要集中在新功能的复杂性上。", "situation": "团队士气低落，有人建议回退到旧版本，有人建议继续优化新版本。用户流失率开始上升。"}', '你会如何应对？', '["立即回退，保住用户", "坚持新版本，继续优化改进", "快速迭代，在一周内发布优化版本", "与核心用户深度访谈，理解真实痛点后决策"]', 3, '正确答案是D。不要急于做决定。深入理解用户反馈背后的真实原因是关键。可能是功能设计问题，也可能是引导不足，或是用户习惯问题。基于真实洞察做决策，避免简单的回退或固执己见。', 3, 'hard', 15, '["产品", "用户反馈", "迭代"]', TRUE);

