-- 4. 运营管理类、5. 创新类、6. 领导力类等
-- 这里仅展示部分示例，实际应该有50道完整题目

-- 示例：运营管理类
INSERT INTO challenges (title, description, scenario, question, options, correctAnswer, explanation, competencyId, difficulty, points, tags, isActive) VALUES
('数据驱动决策', '如何利用数据优化运营', '{"context": "你负责运营一个SaaS产品，发现用户留存率在持续下降。", "situation": "有多个可能的原因：产品bug、竞品竞争、定价问题、用户成功服务不足。团队各有看法，但没有定论。"}', '你会采取什么行动？', '["立即降价，吸引用户回流", "加大市场投放，获取更多新用户", "建立数据分析体系，定位流失环节和原因", "升级产品功能，提升竞争力"]', 2, '正确答案是C。问题出现时，首先要诊断而不是开药方。建立数据分析体系，通过用户行为数据、流失访谈、漏斗分析等方法定位真实原因，然后针对性解决。盲目行动（A、B、D）可能浪费资源且无法根治问题。', 8, 'medium', 10, '["运营", "数据", "用户留存"]', TRUE),

('增长策略选择', '如何实现快速增长', '{"context": "公司要求下季度用户增长100%，目前主要通过内容营销获客。", "situation": "有几个选项：加大内容投入、尝试付费广告、建立渠道合作、开发裂变增长功能。"}', '你会优先选择哪个策略？', '["加大内容投入，因为已经验证有效", "尝试付费广告，快速获得流量", "先做小规模测试，找到ROI最高的渠道", "多管齐下，所有渠道都尝试"]', 2, '正确答案是C。增长要基于实验和迭代。在不确定性高的情况下，小规模快速测试各个渠道，找到投入产出比最优的方案，然后放大投入。过度依赖单一渠道（A）有风险，盲目投入（B）可能浪费，全面出击（D）会分散资源。', 9, 'hard', 15, '["运营", "增长", "策略"]', TRUE);

